Let $(S_1,\dots,S_p)$ be an ordered set partition of $[n]$, and $(s_1,\dots,s_p)$ be a composition of $k$.
	For a set $S$, let $x_S = \sum_{i \in S} x_i$.
	Derksen and Fink~\cite{DerksenFink} showed that the cones determined by the inequalities
	\begin{equation}
		\begin{aligned}
			x_{S_1}          & \leq s_1 \\
			x_{S_1 \cup S_2} & \leq s_1+s_2 \\
			                 & \vdots \\
			x_{[n]}          & \leq k.
		\end{aligned}
	\end{equation}
	form a basis of the valuative ring of matroids on the ground set $[n]$ of rank $k$.

\label{def:flag}
	Let $ (\Delta,\pi) $
	be completely balanced with $\pi = (V_1, \ldots,V_m)$.The \emph{color} of a vertex $ x\in V_i $ is $ \operatorname{color}(x)=i $, and the \emph{type} of a face $ F\in\Delta $ is
	\begin{equation}
		\operatorname{type}(F)=\{\operatorname{color}(x):x\in F\}\subseteq[m].
	\end{equation}
	For $ S\subseteq[m] $ the \emph{flag $ f $-number} and the \emph{flag $ h $-number} of $ \Delta $ are
	\begin{equation}\label{eq:flagnumbers}
		f_S(\Delta)=\#\{F\in\Delta:\operatorname{type}(F)=S\},\qquad
		h_S(\Delta)=\sum_{T\subseteq S}(-1)^{|S\setminus T|}f_T(\Delta).
	\end{equation}

If $\Delta$ is a completely balanced complex, then
	\begin{equation}\label{eq:flagh}
		h_d(\Delta)=\sum_{|S|=d} h_S(\Delta).
	\end{equation}

\label{def:reading_word}
	The \emph{reading word} of an ordered set partition$(S_1,\dots,S_p)$ is the cyclic word $ w $ defined by
	\begin{equation}\label{eq:reading-osp}
		w(i)= j \text{ if } i \in S_j.
	\end{equation}

\label{thm:hmain}
	Let $ \mathcal{T}_{k,n} $ be the triangulation complex of $ \Delta_{k,n} $.
	Then, for each cyclic composition $ \alpha $, we have
	\begin{equation}
		\sum_{S: \operatorname{ccomp}(S) = [\alpha]} h_S(\mathcal{T}_{k,n}) = \left| \left\{ \mathsf{S} \in \operatorname{hDOSP}(k,n): \operatorname{ccomp}(\operatorname{cDes}(\mathsf{S})) = [\alpha] \right\}\right|.
	\end{equation}

\label{thm:repmain}
	Let $ \gcd(k,n)=1 $ and let $ S $
	be a nonempty subset of $ [n] $ with $\operatorname{ccomp}(S) = [\alpha]$. Then
	\begin{equation}
		k \, f_S(\mathcal{T}_{k,n}) = \dim \operatorname{Hom}_{S_n}(M^{\alpha}, \mathcal{M}_{k,n})
	\end{equation}

\label{thm:max_face}
	If $ (I_0,\dots,I_{n-1}) $
	is a maximal face in $ \mathcal{T}_{k,n} $
, then there exists a permutation $ w \in S_n $ with $ \operatorname{cdes}(w) = k $ such that  for any $p \in \mathbb{Z}/n\mathbb{Z}$, we have
	\begin{equation}\label{eq:circuit}
		I_{p} = I_{p-1} \setminus \{w^{-1}(p)-1\} \cup \{w^{-1}(p)\}
	\end{equation}
	for all $p \in \mathbb{Z}/n\mathbb{Z}$. Moreover, we may take $w(n)=1$ and
	\begin{equation}\label{eq:cDescirc}
		I_p = \operatorname{cDes}\left(w^{(p)}\right).
	\end{equation}

\label{ex:maxface}
	In Figure~\ref{fig:d24}, the four simplices triangulating the hypersimplex $\Delta_{2,4}$ are shown in Table~\ref{tab:d24}.
	Take the second row in that table where $w^{(0)} = 4213$ with $\operatorname{cDes}(w^{(0)}) = \{1,2\}$. We have
	\begin{align*}
		w^{(1)} & = 3142, & \operatorname{cDes}(w^{(1)}) = \{1,3\}, \\
		w^{(2)} & = 2431, & \operatorname{cDes}(w^{(2)}) = \{2,3\}, \\
		w^{(3)} & = 1324, & \operatorname{cDes}(w^{(3)}) = \{2,4\}.
	\end{align*}

\label{cor:gcd}
	The functions $j \mapsto f_{S+j}(\mathcal{T}_{k,n})$ and $j \mapsto h_{S+j}(\mathcal{T}_{k,n})$ only depend on $j \bmod d$ and
	are constant when $\gcd(k,n)=1$.

\label{lem:alcove_to_word}
	For any face $ F \in \mathcal{T}_{k,n} $ of dimension $ p-1 $,
	\begin{enumerate}
		\item there exists an ordering $ F =(I_0,\dots,I_{p-1}) $ of its vertices such that $I_0$ is lexicographically
		minimal, denoted $ \operatorname{base}(F):= I_0 $. Moreover, let $\alpha_i = e_{i} - e_{i-1}$ for $i \in \{2,\dots,n\}$, then
		for any $p \geq 1$, we let $I_{p} - I_{p-1} = \alpha_{A_i}:= \sum_{j\in A_i}\alpha_j$, for some subset $A_i \subseteq [n]$.
		\item The $ A_i $'s are mutually disjoint. Let $ A_{p}:= [n] \setminus \left(\bigcup_{i=1}^{p-1} A_i\right) $.
		\item Let $ w_F: [n] \to [p] $ be the word defined by
		\begin{equation}\label{eq:wF}
			w_F(i) = \min\{t: i \in A_1 \cup \cdots \cup A_t\},
		\end{equation}
		then
		\begin{equation}\label{eq:Fdeseq}
			\operatorname{cDes}(w_F) \subseteq \operatorname{base}(F) \subseteq \operatorname{cDes}(w_F) \cup \operatorname{cEq}(w_F).
		\end{equation}
		Conversely, for any word $ w: \mathbb{Z}/n\mathbb{Z} \to \mathbb{Z}/p\mathbb{Z} $ with $ \operatorname{cdes}(w) \leq k $ and any $ k $ -subset $ I $ in $ [n] $ such that
		\begin{equation}\label{eq:deseq}
			\operatorname{cDes}(w) \subseteq I \subseteq \operatorname{cDes}(w) \cup \operatorname{cEq}(w),
		\end{equation}
		there is a face $ F = (I = I_1,\dots,I_{p}) $ for which $ w = w_F $.
		\item Fix some word $ w: \mathbb{Z}/n\mathbb{Z} \to \mathbb{Z}/p\mathbb{Z} $. The number of $ I \in \binom{[n]}{k} $
		satisfying~\eqref{eq:deseq} is
		\[
			\binom{\operatorname{ceq}(w)}{k - \operatorname{cdes}(w)}.
		\]
	\end{enumerate}

\label{prop:compF}
	Let $ \alpha \models n $
	be a composition with $ p $ parts. The number of nonempty faces $ F \in \mathcal{T}_{k,n} $ with $ \operatorname{comp}(F) = \alpha $ is equal to
	\begin{equation}\label{eq:Nalpha}
		\sum_{\substack{w \in W(\alpha) \\ w(n) = 1}} \binom{\operatorname{ceq}(w)}{k - \operatorname{cdes}(w)}.
	\end{equation}

Let $ [\alpha] $ be a cyclic composition. Then
	\begin{equation}
		\sum_{\substack{S \subseteq [n] \\ \operatorname{ccomp}(S) \in [\alpha]}} f_S(\mathcal{T}_{k,n}) = \sum_{\beta \in [\alpha]} \sum_{\substack{w \in W(\beta) \\ w(n) = 1}} \binom{\operatorname{ceq}(w)}{k - \operatorname{cdes}(w)}.
	\end{equation}

For all $ 0 < k < n $
	and every nonempty subset $ S \subseteq[n] $ with $ |S| = p $, over $\mathbb{Q}[q]/(q^n-1) $, we have
	\begin{equation}
		f_S(\mathcal{T}_{k,n}) = \sum_{i \in S} [q^i] \sum_{\substack{\operatorname{content}(w) = \operatorname{comp}^{(i)}(S) \\ w(n) = 1}} q^{\operatorname{cmaj}(w)} e_{k-\operatorname{des}(w)}\left( q^j: j \in \operatorname{cEq}(w) \right)
	\end{equation}
	where
	\begin{equation}
		\operatorname{cmaj}(w):= \sum_{i \in \operatorname{cDes}(w)} i
	\end{equation}
	is the \emph{cyclic major index}

\label{lem:alphap}
	Let $ \alpha = (\alpha_1,\dots,\alpha_p) \models n $. Then
	\begin{equation}
		\alpha_1 \sum_{w \in W(\alpha)} \binom{\operatorname{ceq}(w)}{k-\operatorname{cdes}(w)} = n \sum_{\substack{w \in W(\alpha) \\ w(n) = 1}} \binom{\operatorname{ceq}(w)}{k - \operatorname{cdes}(w)}.
	\end{equation}

\label{thm:GHyp}
	For all $n \geq 2$ and $1 \leq k \leq n-1$, we have
	\begin{equation}
		G_{k,n}= \frac{n}{k} \operatorname{Hyp}_{k,n}
	\end{equation}

\label{lem:Gtrace}
	\begin{equation}
		\sum_{k \geq 0} G_{k,n}(x_1,\dots,x_n) z^k = \operatorname{tr}((\Theta X)^n).
	\end{equation}

Expanding the trace of the $ n $ -th power of $ \Theta X $, the trace is
	\begin{equation}
		\operatorname{tr}((\Theta X)^n) = \sum_{w: \mathbb{Z}/n\mathbb{Z} \to \mathbb{Z}_{>0}} \prod_{i \in \mathbb{Z}/n\mathbb{Z}} \Theta_{w(i)w(i+1)} x_{w(i+1)}
	\end{equation}
	the sum being over all cyclic words of length $ n $. If $ w(i) < w(i+1) $, then $
		\Theta_{w(i)w(i+1)} = 1 $; if $ w(i) = w(i+1) $, i.e. $ i \in \operatorname{cEq}(w) $, then $
		\Theta_{w(i)w(i+1)} = 1+z $; if $ w(i) > w(i+1) $, i.e. $ i \in \operatorname{cDes}(w) $, then $
		\Theta_{w(i)w(i+1)} = z $. Therefore,
	\begin{equation}
		\operatorname{tr}((\Theta X)^n) = \sum_{w: \mathbb{Z}/n\mathbb{Z} \to \mathbb{Z}} z^{\operatorname{cdes}(w)} (1+z)^{\operatorname{ceq}(w)} x^w = \sum_{w: \mathbb{Z}/n\mathbb{Z} \to \mathbb{Z}} \sum_{k \geq 0} \binom{\operatorname{ceq}(w)}{k-\operatorname{cdes}(w)} z^k x^w.
	\end{equation}

\label{lem:detI-t}
	Then
	\begin{equation}
		\det(I - t \Theta X) = \frac{1}{1-z} \left( \frac{1}{H(t)} - \frac{z}{H(zt)} \right).
	\end{equation}

Let $ \Theta^{(j)} $ be the principal $ j \times j $ -minor of $ \Theta $. The determinants of $ \Theta^{(j)} $
	satisfy the following recursion.
	\begin{equation}
		\det \Theta^{(j)} = (1+z) \det \Theta^{(j-1)} - z \det \Theta^{(j-2)}
	\end{equation}
	with initial conditions $
		\det \Theta^{(0)} = 1 $ and $
		\det \Theta^{(1)} = 1+z $.
	By induction, we can show that $
		\det \Theta^{(j)} = [j+1]_z = 1 + z + \cdots + z^j = \frac{1 - z^{j+1}}{1-z} $.
	We expand the determinant
	\begin{equation}
		\det(I - t\Theta X) = \sum_{j \geq 0} (-t)^j \sum_{|S|=j} \det(\Theta_{S,S}) x^S.
	\end{equation}
	Then
	\begin{multline}
		\det(I - t\Theta X) = \sum_{j \geq 0} (-1)^j [j+1]_z e_j t^j \\= \frac{1}{1-z} \left( \sum_{j \geq 0} (-1)^j e_j t^j - z \sum_{j \geq 0} (-1)^j e_j (zt)^j \right) \\= \frac{1}{1-z}\left(\frac{1}{H(t)} - \frac{z}{H(zt)}\right).
	\end{multline}

We have
	\begin{equation}
		\sum_{n \geq 1} \operatorname{Hyp}_{k,n}(x_1,\dots,x_n)t^n = k [z^k] \log \frac{1-z}{H(zt) - z H(t)}.
	\end{equation}

Compute the right hand side by
	\begin{multline}
		H(zt) - z H(t) = \sum_{n \geq 0} h_n (zt)^n - z \sum_{n \geq 0} h_n t^n \\ = h_0(1-z) + z \sum_{n \geq 2} (z^{n-1} - 1) h_n t^n = (1-z) - z(1-z) \sum_{n \geq 0} [n-1]_z h_n t^n.
	\end{multline}
	Therefore,
	\begin{equation}
		\log \frac{1-z}{H(zt) - z H(t)} = \sum_{p \geq 1} \frac{1}{p} \left(z \sum_{n \geq 0} [n-1]_z h_n t^n \right)^p.
	\end{equation}
	Observe that
	\begin{equation}
		z \sum_{n \geq 0} [n-1]_z h_n t^n = \sum_{j \geq 1} z^j \sum_{n \geq j+1} h_n t^n.
	\end{equation}
	The coefficient of $ z^k $ in $
		\left(\sum_{j \geq 1} z^j \sum_{n \geq j+1} h_n t^n \right)^p $ is
	\begin{equation}\label{eq:pair_hyp_cont}
		\sum_{\mu} \sum_\lambda h_\lambda t^{|\lambda|}
	\end{equation}
	where $ \mu = (\mu_1,\dots,\mu_p) $ is a composition of $ k $, $ \lambda = (\lambda_1,\dots,\lambda_p)$
	is composition such that $
		\lambda_i \geq \mu_i + 1 $ for every $ i \in \mathbb{Z}/p\mathbb{Z} $. For any hypersimplicial weak composition $\alpha$, let $\lambda$ be the composition consisting of only positive parts in $\alpha$ in order, and let $\mu$ be the composition such that $\mu_i$ is the circular distance between $\lambda_i$ and $\lambda_{i+1}$.
	Then~\eqref{eq:pair_hyp_cont} is equal to
	\[
		\sum_{\substack{\alpha \in \mathbb{Z}_{\geq0}^{\mathbb{Z}/k\mathbb{Z}}, \\ \alpha \models n, \\ \alpha \text{ is hypersimplicial}}} h_\alpha
	\]
	which is equal to the left hand side.

By Lemma~\ref{lem:Gtrace}
	\begin{equation}
		-\log \det(I - t\Theta X) = \sum_{n \geq 1} \frac{\operatorname{tr}((\Theta X)^n)t^n}{n} = \sum_{n \geq 1} \sum_{k \geq 0} \frac{G_{k,n} z^k t^n}{n}
	\end{equation}
	By Lemma~\ref{lem:detI-t},
	\begin{align}
		-\log \det(I - t\Theta X) & = \log H(t) + \log H(zt) + \log \frac{1-z}{H(zt) - zH(t)} \\
		                          & = \log H(t) + \log H(zt) + \sum_{n \geq 1} \sum_{k \geq 0} \frac{\operatorname{Hyp}_{k,n} t^n z^k}{k}.
	\end{align}
	The error terms $\log H(t)$ and $\log H(zt)$ only contribute to the coefficients of $z^k t^n$ with $k=0$ or $k=n$, so the equality holds for all $1 \leq k \leq n-1$.

\label{thm:ftoG}
	For all $ 0 < k < n $
	and every nonempty subset $ S \subseteq [n] $ with $
		\operatorname{ccomp}(S) = [\alpha]$, we have
	\begin{equation}
		\sum_{j \in \mathbb{Z}/n\mathbb{Z}} f_{S+j}(\mathcal{T}_{k,n}) = \langle h_\alpha, G_{k,n} \rangle.
	\end{equation}

Let
	\[
		N(\alpha) = \sum_{\substack{w \in W(\alpha) \\ w(n) = 1}} \binom{\operatorname{ceq}(w)}{k - \operatorname{cdes}(w)}.
	\]
	By Lemma~\ref{lem:alphap},
	\begin{multline}
		\sum_{j \in \mathbb{Z}/n\mathbb{Z}} f_{S+j}(\mathcal{T}_{k,n})  = \sum_{i=0}^{p-1} N(\alpha^{(i)})
		\\= \frac{1}{n} \sum_{i=0}^{p-1} \alpha_i \sum_{w \in W(\alpha^{(i)})} \binom{\operatorname{ceq}(w)}{k - \operatorname{cdes}(w)} = \sum_{w \in W(\alpha)} \binom{\operatorname{ceq}(w)}{k - \operatorname{cdes}(w)}
	\end{multline}
	because $\langle h_{\alpha^{(i)}}, G_{k,n} \rangle = \langle h_\alpha, G_{k,n} \rangle$ for any $i \in \mathbb{Z}/p\mathbb{Z}$ and $\sum \alpha_i = n$.

Let $ d = \gcd(k,n) $, and let $ S $
	be a nonempty subset of $ [n] $ with $
		\operatorname{ccomp}(S) = [\alpha] $. Then $ f_{S+j}(\mathcal{T}_{k,n}) $ depends on $ j $ only through $ j \bmod d $, and
	\begin{equation}
		\frac{n}{d} \sum_{j=0}^{d-1} f_{S+j}(\mathcal{T}_{k,n}) = \sum_{w \in W(\alpha)} \binom{\operatorname{ceq}(w)}{k - \operatorname{cdes}(w)}.
	\end{equation}

\label{thm:contingency}
	Let $ S \subseteq [n] $ and $
		\operatorname{comp}(S) = \alpha $. Let $ W_S $
	be the set of hypersimplicial words $ w $ with $\operatorname{cDes}(w) \subseteq S $.
	The cardinality of $ W_S $ is
	\begin{equation}
		|W_S| = \langle h_\alpha, \operatorname{Hyp}_{k,n} \rangle.
	\end{equation}
